fn merge_intervals(mut intervals: Vec<(i32, i32)>) -> Vec<(i32, i32)> {
    intervals.sort_by_key(|iv| iv.0);
    let mut merged: Vec<(i32, i32)> = Vec::new();
    for (start, end) in intervals {
        if let Some(last) = merged.last_mut() {
            if start <= last.1 {
                last.1 = last.1.max(end);
                continue;
            }
        }
        merged.push((start, end));
    }
    merged
}

fn edit_distance(word1: &str, word2: &str) -> usize {
    let a: Vec<char> = word1.chars().collect();
    let b: Vec<char> = word2.chars().collect();
    let (m, n) = (a.len(), b.len());
    let mut dp = vec![vec![0usize; n + 1]; m + 1];
    for i in 0..=m { dp[i][0] = i; }
    for j in 0..=n { dp[0][j] = j; }
    for i in 1..=m {
        for j in 1..=n {
            dp[i][j] = if a[i-1] == b[j-1] {
                dp[i-1][j-1]
            } else {
                1 + dp[i-1][j].min(dp[i][j-1]).min(dp[i-1][j-1])
            };
        }
    }
    dp[m][n]
}

use std::collections::HashSet;

fn word_break(s: &str, word_dict: &[&str]) -> bool {
    let words: HashSet<&str> = word_dict.iter().copied().collect();
    let n = s.len();
    let mut dp = vec![false; n + 1];
    dp[0] = true;
    for i in 1..=n {
        for j in 0..i {
            if dp[j] && words.contains(&s[j..i]) {
                dp[i] = true;
                break;
            }
        }
    }
    dp[n]
}

int numIslands(vector<vector<char>>& grid) {
    if (grid.empty()) return 0;
    int rows = grid.size(), cols = grid[0].size(), count = 0;
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    vector<pair<int,int>> dirs = {{1,0},{-1,0},{0,1},{0,-1}};
    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (grid[r][c] == '1' && !visited[r][c]) {
                count++;
                vector<pair<int,int>> stack = {{r, c}};
                while (!stack.empty()) {
                    auto [cr, cc] = stack.back(); stack.pop_back();
                    if (cr < 0 || cr >= rows || cc < 0 || cc >= cols) continue;
                    if (visited[cr][cc] || grid[cr][cc] != '1') continue;
                    visited[cr][cc] = true;
                    for (auto& [dr, dc] : dirs) stack.push_back({cr + dr, cc + dc});
                }
            }
        }
    }
    return count;
}

vector<int> topologicalSort(int numNodes, vector<pair<int,int>>& edges) {
    vector<vector<int>> graph(numNodes);
    vector<int> indegree(numNodes, 0);
    for (auto& [a, b] : edges) {
        graph[a].push_back(b);
        indegree[b]++;
    }
    queue<int> q;
    for (int i = 0; i < numNodes; ++i) if (indegree[i] == 0) q.push(i);
    vector<int> order;
    while (!q.empty()) {
        int node = q.front(); q.pop();
        order.push_back(node);
        for (int next : graph[node]) {
            if (--indegree[next] == 0) q.push(next);
        }
    }
    return order.size() == (size_t)numNodes ? order : vector<int>();
}

string minWindow(string s, string t) {
    if (s.empty() || t.empty()) return "";
    unordered_map<char, int> need;
    for (char c : t) need[c]++;
    int missing = t.size(), left = 0, start = 0, end = 0;
    for (int right = 1; right <= (int)s.size(); ++right) {
        char c = s[right - 1];
        if (need.count(c) && need[c]-- > 0) missing--;
        while (missing == 0) {
            if (end == 0 || right - left < end - start) { start = left; end = right; }
            char lc = s[left];
            if (need.count(lc) && ++need[lc] > 0) missing++;
            left++;
        }
    }
    return s.substr(start, end - start);
}

